css:
.stage{position:relative;isolation:isolate}
.stage__line{position:absolute;left:12%;bottom:210px;width:66%;height:3px;
  background:#00a5b5;transform:rotate(-17deg);transform-origin:left center;z-index:0}
.stage__line::before{content:"";position:absolute;left:-1px;top:-7px;
  border:8px solid transparent;border-right-color:#00a5b5}
.stage__subject{position:relative;z-index:2}   /* 背景透過の切り抜き人物 */
.stage__main{position:absolute;z-index:3;color:#3b2b22;font-size:26px;font-weight:700}
.stage__sub {position:absolute;z-index:1;color:#c9ced2;font-size:18px;font-weight:400}
